 .deal-strip,
 .deals-grid,
 .editorial-grid,
 .product-grid {
   width: 100%;
 }

 .site-header {
   display: flex;
   align-items: center;
   justify-content: space-between;
   gap: 24px;
   padding: 18px 22px;
   border: 1px solid rgba(255, 255, 255, 0.4);
   border-radius: var(--radius-lg);
   background: rgba(255, 255, 255, 0.58);
   backdrop-filter: blur(14px);
   box-shadow: var(--shadow);
 }

 .brand-lockup {
   display: flex;
   align-items: center;
   gap: 14px;
 }

 .brand-mark {
   display: grid;
   place-items: center;
   width: 46px;
   height: 46px;
   border-radius: 16px;
   background: linear-gradient(135deg, var(--surface-dark), #2d2d2d);
   color: white;
   font-weight: 800;
 }

 .brand-lockup h1,
 .eyebrow,
 .hero h2,
 .section-head h3,
 .product-card h4,
 .deal-card h4,
 .editorial-card h4 {
   margin: 0;
 }

 .eyebrow {
   font-size: 0.78rem;
   font-weight: 700;
   letter-spacing: 0.12em;
   text-transform: uppercase;
   color: var(--muted);
 }

 .site-nav {
   display: flex;
   align-items: center;
   gap: 28px;
   font-weight: 500;
   color: #303038;
 }

 .site-nav a:hover,
 .text-link:hover,
 .card-footer a:hover,
 .editorial-copy a:hover {
   color: var(--accent);
 }

 .action-pill,
 .primary-button,
 .secondary-button,
 .filter-chip,
 .ghost-button {
   border: 0;
   cursor: pointer;
   transition:
     transform 160ms ease,
     background-color 160ms ease,
     color 160ms ease,
     border-color 160ms ease,
     opacity 160ms ease;
 }

 .action-pill,
 .primary-button,
 .secondary-button,
 .filter-chip {
   border-radius: var(--radius-sm);
 }

 .action-pill,
 .primary-button {
   background: var(--surface-dark);
   color: white;
 }

 .action-pill,
 .secondary-button,
 .filter-chip,
 .ghost-button {
   padding: 12px 18px;
 }

 .action-pill:hover,
 .primary-button:hover,
 .secondary-button:hover,
 .filter-chip:hover,
 .ghost-button:hover {
   transform: translateY(-1px);
 }

 .hero {
   display: grid;
   grid-template-columns: 1.1fr 0.9fr;
   gap: 34px;
   margin-top: 24px;
   padding: 32px;
   border-radius: var(--radius-xl);
   background: linear-gradient(140deg, rgba(255, 255, 255, 0.84), rgba(255, 255, 255, 0.56));
   box-shadow: var(--shadow);
   overflow: hidden;
 }

 .hero-copy {
   padding: 12px 4px 12px 6px;
 }

 .hero h2 {
   margin-top: 10px;
   font-size: clamp(2.7rem, 5vw, 5.2rem);
   line-height: 0.96;
   letter-spacing: -0.06em;
   max-width: 11ch;
 }

 .hero-text {
   max-width: 56ch;
   margin: 20px 0 0;
   font-size: 1.05rem;
   line-height: 1.7;
   color: var(--muted);
 }

 .hero-actions,
 .filter-group {
   display: flex;
   flex-wrap: wrap;
   gap: 12px;
 }

 .hero-actions {
   margin-top: 28px;
 }

 .primary-button,
 .secondary-button {
   display: inline-flex;
   align-items: center;
   justify-content: center;
   padding: 14px 22px;
   font-weight: 600;
 }

 .secondary-button,
 .filter-chip,
 .ghost-button {
   background: rgba(255, 255, 255, 0.7);
   color: var(--text);
   border: 1px solid var(--line);
 }

 .hero-metrics {
   display: flex;
   flex-wrap: wrap;
   gap: 16px;
   margin: 34px 0 0;
 }

 .hero-metrics div {
   min-width: 132px;
   padding: 16px 18px;
   border-radius: var(--radius-md);
   background: rgba(255, 255, 255, 0.72);
   border: 1px solid rgba(255, 255, 255, 0.5);
 }

 .hero-metrics dt {
   font-size: 1.3rem;
   font-weight: 800;
 }

 .hero-metrics dd {
   margin: 8px 0 0;
   color: var(--muted);
   line-height: 1.5;
 }

 .hero-visual {
   position: relative;
   min-height: 500px;
   border-radius: calc(var(--radius-xl) - 6px);
   background:
     linear-gradient(180deg, rgba(29, 78, 216, 0.08), transparent 35%),
     linear-gradient(145deg, #efeae1, #e7ecf6);
 }

