 const filterButtons = document.querySelectorAll(".filter-chip");
 const productCards = document.querySelectorAll(".product-card");

 filterButtons.forEach((button) => {
   button.addEventListener("click", () => {
     const selectedFilter = button.dataset.filter;

     filterButtons.forEach((chip) => {
       const isSelected = chip === button;
       chip.classList.toggle("is-active", isSelected);
       chip.setAttribute("aria-selected", String(isSelected));
     });

     productCards.forEach((card) => {
       const matches =
         selectedFilter === "all" || card.dataset.category === selectedFilter;
       card.classList.toggle("is-hidden", !matches);
       card.hidden = !matches;
     });
   });
 });

 const countdownTarget = new Date(Date.now() + 2 * 24 * 60 * 60 * 1000 + 18 * 60 * 60 * 1000 + 42 * 60 * 1000 + 16 * 1000);
 const timeFields = {
   days: document.getElementById("days"),
   hours: document.getElementById("hours"),
   minutes: document.getElementById("minutes"),
   seconds: document.getElementById("seconds"),
 };

 function updateCountdown() {
   const timeRemaining = countdownTarget.getTime() - Date.now();

   if (timeRemaining <= 0) {
     timeFields.days.textContent = "00";
     timeFields.hours.textContent = "00";
     timeFields.minutes.textContent = "00";
     timeFields.seconds.textContent = "00";
     return;
   }

   const day = 24 * 60 * 60 * 1000;
   const hour = 60 * 60 * 1000;
   const minute = 60 * 1000;

   const days = Math.floor(timeRemaining / day);
   const hours = Math.floor((timeRemaining % day) / hour);
   const minutes = Math.floor((timeRemaining % hour) / minute);
   const seconds = Math.floor((timeRemaining % minute) / 1000);

   timeFields.days.textContent = String(days).padStart(2, "0");
   timeFields.hours.textContent = String(hours).padStart(2, "0");
   timeFields.minutes.textContent = String(minutes).padStart(2, "0");
   timeFields.seconds.textContent = String(seconds).padStart(2, "0");
 }

 updateCountdown();
 setInterval(updateCountdown, 1000);

